#include <iostream>
#include <stack>
using namespace std;

int main() {
    stack<char>a;
    string st;cin>>st;
    for(int i=0;i<st.length();i++)
    {
        if(st[i]=='(')a.push(st[i]);
        else if(a.empty())cout<<"ValueError: Parentheses not balanced";
        else a.pop();
    }
    if(a.empty())cout<<"true";
    else cout<<"ValueError: Parentheses not balanced";
}

