s = input()

def daungoac(s):
    stack = []
    for ch in s:
        if ch == '(':
            stack.append(ch)
        elif  ch == ')' and len(stack) == 0:
            return "false"
        elif ch == ')' and stack[-1] == '(':
            stack.pop()
    if len(stack) == 0:
        return "true"
    else:
        return "ValueError: Parentheses not balanced"
print(daungoac(s))

